const rows = parseCsv(fs.readFileSync(SALES_PATH, 'utf8'));
const summary = computeMonthly(rows);
const generated = toCsv(summary);

if (process.argv.includes('--write')) {
  fs.writeFileSync(SUMMARY_PATH, generated);
  console.log(`WROTE ${SUMMARY_PATH}`);
}

if (fs.existsSync(SUMMARY_PATH)) {
  const diffs = verify(fs.readFileSync(SUMMARY_PATH, 'utf8'), generated);
  if (diffs.length === 0) {
    console.log('VERIFY PASSED: monthly_summary.csv matches recomputed results.');

